USE ipl2026;

DROP TABLE IF EXISTS matches;

CREATE TABLE matches (
  match_id INT PRIMARY KEY,
  date DATE,
  venue VARCHAR(100),
  team1 VARCHAR(10),
  team2 VARCHAR(10),
  stage VARCHAR(20),
  toss_winner VARCHAR(10),
  toss_decision VARCHAR(10),
  first_ings_score INT,
  first_ings_wkts INT,
  second_ings_score INT,
  second_ings_wkts INT,
  match_result VARCHAR(20),
  match_winner VARCHAR(10),
  wb_runs INT,
  wb_wickets INT,
  balls_left INT,
  player_of_the_match VARCHAR(60),
  top_scorer VARCHAR(60),
  highscore INT,
  best_bowling VARCHAR(60),
  best_bowling_figure VARCHAR(10),
  super_over_match VARCHAR(5)
);


SELECT COUNT(*) AS matches_loaded FROM matches;
